// Content with portions generated by generative AI platform
package org.eclipse.kura.core.status;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Properties;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.gpio.GPIOService;
import org.eclipse.kura.gpio.KuraGPIODirection;
import org.eclipse.kura.gpio.KuraGPIOMode;
import org.eclipse.kura.gpio.KuraGPIOPin;
import org.eclipse.kura.gpio.KuraGPIOTrigger;
import org.eclipse.kura.status.CloudConnectionStatusComponent;
import org.eclipse.kura.status.CloudConnectionStatusEnum;
import org.eclipse.kura.status.CloudConnectionStatusService;
import org.eclipse.kura.system.SystemService;
import org.junit.After;
import org.junit.Test;
import org.osgi.service.component.ComponentContext;

public class BlinkingLedNotificationTest {

    private static final int GPIO_TERMINAL = 44;
    private static final int PHASES_PER_KIND = 5;
    private static final int AWAIT_TIMEOUT_SECONDS = 30;

    private final List<Boolean> ledValues = Collections.synchronizedList(new ArrayList<>());
    private final List<Long> ledTimestamps = Collections.synchronizedList(new ArrayList<>());
    private final List<Long> onPhasesMillis = new ArrayList<>();
    private final List<Long> offPhasesMillis = new ArrayList<>();

    private CountDownLatch blinkPhasesObserved;
    private CloudConnectionStatusServiceImpl service;

    @Test
    public void fastBlinkingTogglesLedEveryHundredMilliseconds() throws Exception {
        givenServiceDrivingGpioLed();

        whenComponentReportsStatus(CloudConnectionStatusEnum.FAST_BLINKING);

        thenBlinkPhasesAreObserved();
        thenMedianOnPhaseIsBetween(80, 200);
        thenMedianOffPhaseIsBetween(80, 200);
    }

    @Test
    public void slowBlinkingTogglesLedEveryThreeHundredMilliseconds() throws Exception {
        givenServiceDrivingGpioLed();

        whenComponentReportsStatus(CloudConnectionStatusEnum.SLOW_BLINKING);

        thenBlinkPhasesAreObserved();
        thenMedianOnPhaseIsBetween(280, 1000);
        thenMedianOffPhaseIsBetween(280, 1000);
    }

    @After
    public void stopService() {
        if (this.service != null) {
            this.service.deactivate(mock(ComponentContext.class));
        }
    }

    private void givenServiceDrivingGpioLed() throws Exception {
        this.blinkPhasesObserved = new CountDownLatch(2 * PHASES_PER_KIND + 1);

        Properties properties = new Properties();
        properties.setProperty("ccs.status.notification.url", "ccs:led:" + GPIO_TERMINAL);
        SystemService systemService = mock(SystemService.class);
        when(systemService.getProperties()).thenReturn(properties);

        KuraGPIOPin pin = mock(KuraGPIOPin.class);
        when(pin.isOpen()).thenReturn(true);
        doAnswer(invocation -> {
            recordLedWrite(invocation.getArgument(0));
            return null;
        }).when(pin).setValue(anyBoolean());

        GPIOService gpioService = mock(GPIOService.class);
        when(gpioService.getPinByTerminal(GPIO_TERMINAL, KuraGPIODirection.OUTPUT, KuraGPIOMode.OUTPUT_OPEN_DRAIN,
                KuraGPIOTrigger.NONE)).thenReturn(pin);

        this.service = new CloudConnectionStatusServiceImpl();
        this.service.setSystemService(systemService);
        this.service.setGPIOService(gpioService);
        this.service.activate(mock(ComponentContext.class));
    }

    private void whenComponentReportsStatus(CloudConnectionStatusEnum status) {
        this.service.register(new FixedStatusComponent(status));
    }

    private void thenBlinkPhasesAreObserved() throws InterruptedException {
        assertTrue("LED did not blink in time", this.blinkPhasesObserved.await(AWAIT_TIMEOUT_SECONDS, TimeUnit.SECONDS));

        synchronized (this.ledValues) {
            int firstOn = this.ledValues.indexOf(true);
            for (int i = firstOn + 1; i < this.ledValues.size(); i++) {
                long phaseMillis = TimeUnit.NANOSECONDS.toMillis(this.ledTimestamps.get(i) - this.ledTimestamps.get(i - 1));
                (this.ledValues.get(i - 1) ? this.onPhasesMillis : this.offPhasesMillis).add(phaseMillis);
            }
        }
    }

    private void thenMedianOnPhaseIsBetween(long minMillis, long maxMillis) {
        thenMedianIsBetween("on", this.onPhasesMillis, minMillis, maxMillis);
    }

    private void thenMedianOffPhaseIsBetween(long minMillis, long maxMillis) {
        thenMedianIsBetween("off", this.offPhasesMillis, minMillis, maxMillis);
    }

    private void thenMedianIsBetween(String phase, List<Long> phasesMillis, long minMillis, long maxMillis) {
        Collections.sort(phasesMillis);
        long median = phasesMillis.get(phasesMillis.size() / 2);

        assertTrue("median " + phase + " phase was " + median + " ms, phases " + phasesMillis,
                median >= minMillis && median < maxMillis);
    }

    private void recordLedWrite(boolean value) {
        synchronized (this.ledValues) {
            boolean blinking = value || this.ledValues.contains(true);
            this.ledValues.add(value);
            this.ledTimestamps.add(System.nanoTime());
            if (blinking) {
                this.blinkPhasesObserved.countDown();
            }
        }
    }

    private static final class FixedStatusComponent implements CloudConnectionStatusComponent {

        private CloudConnectionStatusEnum status;

        private FixedStatusComponent(CloudConnectionStatusEnum status) {
            this.status = status;
        }

        @Override
        public int getNotificationPriority() {
            return CloudConnectionStatusService.PRIORITY_MEDIUM;
        }

        @Override
        public CloudConnectionStatusEnum getNotificationStatus() {
            return this.status;
        }

        @Override
        public void setNotificationStatus(CloudConnectionStatusEnum status) {
            this.status = status;
        }
    }
}
